export async function placeOrder(cart: Cart, customer: string, o: PlaceOptions): Promise<Placed> {
  if (!cart.lines.length) throw new Error('the cart is empty')
  const started = Date.now()
  // An order already sent from this cart (a double click, a reload): wait on that one instead of sending another.
  const open = await api.get<{ id: string } | null>(`/api/carts/${cart.id}/open-order`)
  if (open) {
    o.progress('Your order is already on its way')
    return { orderId: open.id, outcome: await waitForPayment(open.id, o.timeoutMs, o.progress) }
  }
  const req = buildOrder(cart, customer)
  // Validate first: stock and prices are checked before the customer is sent to their bank.
  try {
    await api.post('/api/orders?dryRun=1', req)
  } catch (e) {
    if (e instanceof ApiError && e.status === 409) {
      o.progress('Some items just sold out; the cart was updated')
      throw e
    }
    throw e
  }
  o.progress('Sending your order')
  const created = await api.post<{ id: string; status: string }>('/api/orders', req)
  if (created.status === 'paid') {
    return { orderId: created.id, outcome: { status: 'paid', message: '' } }
  }
  o.progress('Waiting for the payment')
  const left = Math.max(o.timeoutMs - (Date.now() - started), 1000)
  return { orderId: created.id, outcome: await waitForPayment(created.id, left, o.progress) }
}

export function buildOrder(cart: Cart, customer: string, giftNote?: string): OrderRequest {
  const lines = cart.lines
    .filter((l) => l.quantity > 0)
    .map((l) => ({ sku: l.sku, quantity: Math.min(l.quantity, 99), shownPrice: l.shownPrice }))
  if (!lines.length) throw new Error('nothing to order')
  const total = lines.reduce((sum, l) => sum + l.quantity * l.shownPrice, 0)
  // One key per cart: a retried request is the same order, never a second one.
  const idempotencyKey = `cart-${cart.id}-${lines.map((l) => `${l.sku}x${l.quantity}`).join('.')}`
  const req: OrderRequest = {
    cartId: cart.id,
    customer,
    lines,
    shipping: { ...cart.shipping, country: cart.shipping.country.toUpperCase() },
    total,
    idempotencyKey,
  }
  if (cart.coupon) req.coupon = cart.coupon.trim().toUpperCase()
  // A gift note travels as text; the server never renders it as HTML.
  if (giftNote) {
    const note = giftNote.trim().slice(0, 500)
    if (note) req.giftNote = note
  }
  if (total > 1_000_000) {
    throw new Error(`orders over ${money(1_000_000)} go through sales`)
  }
  return req
}

export async function waitForPayment(id: string, timeoutMs: number, progress: (line: string) => void): Promise<PaymentOutcome> {
  if (timeoutMs <= 0) timeoutMs = 10 * 60 * 1000
  const deadline = Date.now() + timeoutMs
  let last = ''
  for (;;) {
    const order = await api.get<{ status: string; message: string }>(`/api/orders/${id}`)
    if (order.message && order.message !== last) {
      progress(order.message)
      last = order.message
    }
    switch (order.status) {
      case 'paid':
        return { status: 'paid', message: '' }
      case 'failed':
        return { status: 'failed', message: order.message || 'the payment failed' }
      case 'cancelled':
        return { status: 'cancelled', message: 'the order was cancelled' }
    }
    if (Date.now() > deadline) {
      // The order is not cancelled: the worker keeps going and the receipt still arrives by email.
      return { status: 'timeout', message: 'still waiting for your bank; we will email you when it is paid' }
    }
    await new Promise((r) => setTimeout(r, POLL_MS))
  }
}

func (s *Server) createOrder(w http.ResponseWriter, r *http.Request) {
	var req OrderRequest
	if err := json.NewDecoder(http.MaxBytesReader(w, r.Body, 64<<10)).Decode(&req); err != nil {
		httpError(w, http.StatusBadRequest, "not a valid order: "+err.Error())
		return
	}
	if len(req.Lines) == 0 || len(req.Lines) > 50 {
		httpError(w, http.StatusBadRequest, "an order has 1 to 50 lines")
		return
	}
	if strings.TrimSpace(req.IdempotencyKey) == "" {
		httpError(w, http.StatusBadRequest, "idempotencyKey is required")
		return
	}
	// The same key twice (a double click, a retry): answer with the order that exists.
	if old, err := s.Store.Orders().ByKey(r.Context(), req.IdempotencyKey); err == nil {
		writeJSON(w, http.StatusOK, old)
		return
	} else if !errors.Is(err, store.ErrNotFound) {
		httpError(w, http.StatusInternalServerError, err.Error())
		return
	}
	priced, err := s.Catalog.Price(r.Context(), req.Lines, req.Coupon)
	if err != nil {
		httpError(w, http.StatusBadRequest, err.Error())
		return
	}
	if priced.Total != req.Total {
		httpError(w, http.StatusConflict, "prices changed; reload the cart")
		return
	}
	if short := s.Stock.Short(r.Context(), req.Lines); len(short) > 0 {
		writeJSON(w, http.StatusConflict, map[string]any{"error": "sold out", "skus": short})
		return
	}
	// Back-ordered items do not refuse the order: the customer is told it will wait.
	preview, err := s.Worker.Preview(r.Context(), &store.Order{Lines: priced.Lines, CreatedAt: time.Now()})
	if err != nil {
		httpError(w, http.StatusInternalServerError, err.Error())
		return
	}
	if r.URL.Query().Get("dryRun") == "1" {
		writeJSON(w, http.StatusOK, map[string]any{"total": priced.Total, "wait": preview.Message})
		return
	}
	now := time.Now().UTC()
	o := &store.Order{
		ID:             store.NewID(),
		CartID:         req.CartID,
		Customer:       req.Customer,
		Lines:          priced.Lines,
		Total:          priced.Total,
		Currency:       s.Cfg.Currency,
		Shipping:       store.Address(req.Shipping),
		GiftNote:       req.GiftNote,
		IdempotencyKey: req.IdempotencyKey,
		Status:         store.OrderPending,
		Message:        "Order received",
		CreatedAt:      now,
		UpdatedAt:      now,
	}
	exp := s.expiry(now)
	o.ExpiresAt = &exp
	if preview.Wait {
		o.Reason, o.Message = store.ReasonStock, preview.Message
	}
	// The order's own reference for the payment provider, so a charge can be matched back to it.
	o.PaymentRef = "ord_" + o.ID
	if err := s.Store.Orders().Create(r.Context(), o); err != nil {
		if errors.Is(err, store.ErrDuplicate) {
			httpError(w, http.StatusConflict, "this order was just placed")
			return
		}
		httpError(w, http.StatusInternalServerError, err.Error())
		return
	}
	s.Log.Info("order stored", "id", o.ID, "total", o.Total, "lines", len(o.Lines))
	writeJSON(w, http.StatusCreated, o)
}

func (w *Worker) loop(ctx context.Context, phase string) {
	interval := w.Interval
	if interval <= 0 {
		interval = 2 * time.Second
	}
	t := time.NewTicker(interval)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-t.C:
		}
		w.pass(ctx, phase)
	}
}

func (w *Worker) processOrder(ctx context.Context, o *store.Order) error {
	now := time.Now().UTC()
	switch o.Status {
	case store.OrderPending:
		if ok, err := w.admit(ctx, o, w.open); !ok || err != nil {
			return err
		}
		// Stock first: a sold-out line fails the order before anyone is charged.
		if err := w.Store.Stock().Reserve(ctx, o.ID, o.Lines); err != nil {
			if errors.Is(err, store.ErrSoldOut) {
				return w.fail(ctx, o, "an item sold out before payment")
			}
			return err
		}
		req, err := payments.BuildCharge(o)
		if err != nil {
			return w.fail(ctx, o, err.Error())
		}
		ch, err := w.Payments.Create(ctx, req)
		if err != nil {
			if payments.Transient(err) {
				return w.retryLater(ctx, o, err.Error())
			}
			_ = w.Store.Stock().Release(ctx, o.ID)
			return w.fail(ctx, o, "the payment could not be started: "+err.Error())
		}
		o.ChargeID = ch.ID
		o.Status = store.OrderCharging
		o.Message = "Confirm the payment with your bank"
		deadline := now.Add(w.Timeout)
		o.Deadline = &deadline
		return w.Store.Orders().Update(ctx, o)

	case store.OrderCharging:
		if o.Deadline != nil && now.After(*o.Deadline) {
			_ = w.Store.Stock().Release(ctx, o.ID)
			return w.fail(ctx, o, "the bank did not answer in time")
		}
		// Is it paid? Asked of the provider, never taken from the browser's redirect.
		ch, err := w.Payments.Get(ctx, o.ChargeID)
		if err != nil {
			if payments.Transient(err) {
				return nil
			}
			return err
		}
		issues := payments.ChargeIssues(ch, w.Payments.WebhookLog(ctx, o.ChargeID))
		waiting := []string{}
		if ch.Status != payments.Succeeded {
			waiting = append(waiting, "payment")
		}
		if !w.Store.Stock().Reserved(ctx, o.ID) {
			waiting = append(waiting, "stock")
		}
		stage := orderStage(ch, o)
		return applyOutcome(ctx, w.Store, o, stage, waiting, issues)

	case store.OrderCancelling:
		// Void the charge first, so the customer is never charged for an order that no longer exists.
		if o.ChargeID != "" {
			if err := w.Payments.Void(ctx, o.ChargeID); err != nil && !payments.AlreadySettled(err) {
				return err
			}
		}
		if err := w.Store.Stock().Release(ctx, o.ID); err != nil {
			return err
		}
		o.Status, o.Message = store.OrderCancelled, "Cancelled"
		o.UpdatedAt = now
		return w.Store.Orders().Update(ctx, o)

	case store.OrderPaid, store.OrderFailed, store.OrderCancelled:
		return nil
	}
	return fmt.Errorf("order %s: unknown status %q", o.ID, o.Status)
}

func orderStage(ch *payments.Charge, o *store.Order) string {
	switch {
	case ch.Status == payments.Succeeded:
		return "packing"
	case ch.NextAction == "redirect_to_bank":
		return "bank"
	case ch.Status == payments.Processing:
		return "processing"
	}
	if o.Message == "" {
		return "waiting"
	}
	return "charging"
}

func applyOutcome(ctx context.Context, st store.Store, o *store.Order, stage string, waiting []string, issues []payments.Issue) error {
	for _, is := range issues {
		if is.Fatal {
			o.Status, o.Message = store.OrderFailed, is.Message
			return st.Orders().Update(ctx, o)
		}
	}
	switch {
	case len(waiting) == 0:
		if o.Status != store.OrderPaid {
			t := time.Now().UTC()
			o.PaidAt = &t
		}
		o.Status, o.Message = store.OrderPaid, ""
	case stage == "bank":
		o.Message = "Confirm the payment with your bank"
	case stage == "processing":
		o.Message = "Your bank is processing the payment"
	default:
		o.Message = "Waiting for the payment"
	}
	o.UpdatedAt = time.Now().UTC()
	return st.Orders().Update(ctx, o)
}

func BuildCharge(o *store.Order) (*ChargeRequest, error) {
	if o.Total <= 0 {
		return nil, fmt.Errorf("order %s: nothing to charge", o.ID)
	}
	if o.Currency == "" {
		return nil, fmt.Errorf("order %s: no currency", o.ID)
	}
	items := make([]ChargeItem, 0, len(o.Lines))
	var sum int64
	for _, l := range o.Lines {
		items = append(items, ChargeItem{Name: l.Name, Quantity: l.Quantity, Amount: l.Price})
		sum += int64(l.Quantity) * l.Price
	}
	// The lines must add up to what the order says; a coupon is one negative line.
	if o.Discount > 0 {
		items = append(items, ChargeItem{Name: "Discount", Quantity: 1, Amount: -o.Discount})
		sum -= o.Discount
	}
	if sum != o.Total {
		return nil, fmt.Errorf("order %s: lines add up to %d, total is %d", o.ID, sum, o.Total)
	}
	desc := fmt.Sprintf("Order %s", strings.ToUpper(o.ID[:8]))
	meta := map[string]string{"order": o.ID, "cart": o.CartID}
	if o.GiftNote != "" {
		meta["gift"] = "yes"
	}

	req := &ChargeRequest{
		Amount:         o.Total,
		Currency:       strings.ToLower(o.Currency),
		Reference:      o.PaymentRef,
		Description:    desc,
		ReturnURL:      returnPath + "?order=" + o.ID,
		IdempotencyKey: "charge-" + o.IdempotencyKey,
		Metadata:       meta,
		Items:          items,
		ThreeDSecure:   "auto",
	}
	// Large orders always go through the bank's check, whatever the provider would decide.
	if o.Total >= 50_000 {
		req.ThreeDSecure = "always"
	}
	return req, nil
}

