// ChargeIssues says what went wrong with a charge, from the charge itself and the webhook log the shop keeps.
// The bank's 3-D Secure page is not ours: all the shop sees of it is what the provider reports afterwards.
func ChargeIssues(ch *Charge, webhookLog []string) []Issue {
	var out []Issue
	switch ch.Status {
	case Failed:
		msg := "the payment failed"
		for _, d := range declines {
			if d.re.MatchString(ch.FailureMsg) {
				msg = d.msg
				break
			}
		}
		out = append(out, Issue{Fatal: true, Message: msg})
	case Expired:
		out = append(out, Issue{Fatal: true, Message: "the payment expired at the bank"})
	}
	for _, line := range webhookLog {
		if strings.Contains(line, "signature mismatch") {
			out = append(out, Issue{Message: "a payment notice was rejected; checking with the provider"})
			break
		}
	}
	return out
}

